20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
27	    @Mapping(target = "membershipTier", expression = "java(toMembershipTier(owner))")
28	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /** Fixed city-to-region table used to derive an owner's {@code locality}. */
32	    Map<String, String> CITY_REGION = Map.of(
33	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
34	
35	    /**
36	     * Format an owner's stored names as {@code 'LastName, FirstName'} for the
37	     * read-only {@code displayName} field returned on the Owner DTO.
38	     */
39	    default String toDisplayName(Owner owner) {
40	        return owner.getLastName() + ", " + owner.getFirstName();
41	    }
42	
43	    /**
44	     * Build the owner's initials as the upper-cased first letters of firstName and
45	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}) for the
46	     * read-only {@code initials} field returned on the Owner DTO.
47	     */
48	    default String toInitials(Owner owner) {
49	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
50	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
51	    }
52	
53	    /**
54	     * Derive the owner's read-only {@code membershipTier}: {@code 'SILVER'} when the owner's name was
55	     * unique at creation time ({@code namesakeCount} is 0) and an email is present, otherwise
56	     * {@code 'BRONZE'}.
57	     */
58	    default String toMembershipTier(Owner owner) {
59	        boolean uniqueName = Integer.valueOf(0).equals(owner.getNamesakeCount());
60	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
61	        return uniqueName && hasEmail ? "SILVER" : "BRONZE";
62	    }
63	
64	    /**
65	     * Derive the owner's read-only {@code locality}: the canonical region looked up from the
66	     * owner's city in the fixed city-to-region table ({@code Sydney->NSW, Melbourne->VIC,
67	     * Brisbane->QLD}), or {@code 'UNKNOWN'} when the city is not in the table.
68	     */
69	    default String toLocality(Owner owner) {
70	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
71	    }
72	
73	    Owner toOwner(OwnerDto ownerDto);
74	
75	    @Mapping(target = "id", ignore = true)
76	    @Mapping(target = "pets", ignore = true)
77	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
78	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
79	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
80	    Owner toOwner(OwnerFieldsDto ownerDto);
81	
82	    /**
83	     * Normalize a postal address to its canonical form (trimmed and whitespace-collapsed,
84	     * upper-cased, with common street-type abbreviations expanded) so it is stored, returned and
85	     * compared in one shape. Blank-after-normalization is rejected separately by
86	     * {@code AddressValidation} on the inbound DTO, so this only performs the transform the stored
87	     * value needs.
88	     */
89	    @Named("normalizeAddress")
90	    default String normalizeAddress(String address) {
91	        return AddressNormalizer.normalize(address);
92	    }
93	
94	    /**
95	     * Normalize a telephone number to canonical E.164 form (a leading {@code '+'}, country
96	     * code and national digits) so it is stored and returned in one comparable form and
97	     * duplicates can be detected by comparing these values. Format validity is enforced
98	     * separately by {@code TelephoneValidation} on the inbound DTO, so this only performs
99	     * the transform the stored value needs.
100	     */
101	    @Named("normalizeTelephone")
102	    default String normalizeTelephone(String telephone) {
103	        return TelephoneNormalizer.toE164(telephone);
104	    }
105	
106	    /**
107	     * Normalize an email address by trimming surrounding whitespace and lower-casing
108	     * it so it is stored and returned in a canonical form. Syntactic validity is
109	     * enforced separately by {@code @Email} on the inbound DTO, so this only performs
110	     * the transform the stored value needs.
111	     */
112	    @Named("normalizeEmail")
113	    default String normalizeEmail(String email) {
114	        return email == null ? null : email.trim().toLowerCase();
115	    }
116	
117	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
118	
119	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
120	
121	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
122	        OwnerPageDto ownerPageDto = new OwnerPageDto();
123	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
124	        ownerPageDto.setPage(ownerPage.getNumber());
125	        ownerPageDto.setSize(ownerPage.getSize());
126	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
127	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
128	        return ownerPageDto;
129	    }
130	}
