236	    @Override
237	    @Transactional
238	    public void saveOwner(Owner owner) throws DataAccessException {
239	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
240	        // roll it forward to the next business day so it never lands on a weekend. Everything
241	        // derived from the registration date below must use this adjusted value.
242	        LocalDate registrationDate = toBusinessDay(
243	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
244	        owner.setRegistrationDate(registrationDate);
245	        if (owner.isNew() && ownerRepository.existsByTelephone(owner.getTelephone())) {
246	            throw new DuplicateTelephoneException(owner.getTelephone());
247	        }
248	        if (owner.isNew()
249	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
250	            throw new CityOwnerLimitExceededException(owner.getCity());
251	        }
252	        if (owner.isNew()
253	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
254	            throw new DailyOwnerLimitExceededException(registrationDate);
255	        }
256	        if (owner.isNew()) {
257	            List<Owner> householdMembers = findHouseholdMembers(owner);
258	            if (!householdMembers.isEmpty()) {
259	                if (!owner.isSharesHousehold()) {
260	                    throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
261	                }
262	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
263	            }
264	        }
265	        if (owner.isNew() && owner.getCustomerCode() == null) {
266	            owner.setCustomerCode(generateCustomerCode(owner));
267	        }
268	        if (owner.isNew()) {
269	            owner.setNamesakeCount(countNamesakes(owner));
270	        }
271	        if (owner.getMembershipNumber() == null) {
272	            owner.setMembershipNumber(generateMembershipNumber(owner));
273	        }
274	        ownerRepository.save(owner);
275	
276	    }
277	
278	    /**
279	     * Count the owners that already exist (before this create) sharing the same first name and last
280	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
281	     * unique among the existing owners.
282	     */
283	    private int countNamesakes(Owner owner) {
284	        String firstName = owner.getFirstName();
285	        String lastName = owner.getLastName();
286	        if (firstName == null || lastName == null) {
287	            return 0;
288	        }
289	        return (int) ownerRepository.findAll().stream()
290	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
291	                && lastName.equalsIgnoreCase(existing.getLastName()))
292	            .count();
293	    }
294	
295	    /**
296	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
297	     * last name and the same address. Last names are compared case-insensitively with collapsed
298	     * whitespace; addresses are compared in their canonical normalized form (see
299	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
300	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
301	     * match on.
302	     */
303	    private List<Owner> findHouseholdMembers(Owner owner) {
304	        String lastName = normalizeHouseholdKey(owner.getLastName());
305	        String address = AddressNormalizer.normalize(owner.getAddress());
306	        if (lastName == null || address == null) {
307	            return List.of();
308	        }
309	        return ownerRepository.findAll().stream()
310	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
311	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
312	            .toList();
313	    }
314	
315	    /**
316	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
317	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
318	     * new one is generated. The resolved value is back-filled onto every member that is missing it
319	     * (or has a different one) so all members of the household share the same identifier.
320	     */
321	    private String resolveHouseholdId(List<Owner> members) {
322	        String householdId = members.stream()
323	            .map(Owner::getHouseholdId)
324	            .filter(id -> id != null && !id.isBlank())
325	            .findFirst()
326	            .orElseGet(() -> UUID.randomUUID().toString());
327	        for (Owner member : members) {
328	            if (!householdId.equals(member.getHouseholdId())) {
329	                member.setHouseholdId(householdId);
330	                ownerRepository.save(member);
331	            }
332	        }
333	        return householdId;
334	    }
335	
336	    /**
337	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
338	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
339	     */
340	    private String normalizeHouseholdKey(String value) {
341	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
342	    }
343	
344	    /**
345	     * Build an owner's {@code customerCode} as {@code '<CITY3>-<LAST3>-<NNNN>'}: CITY3 is the
346	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
347	     * letters of the owner's last name, and NNNN a per-city 4-digit zero-padded sequence equal
348	     * to one more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
349	     */
350	    private String generateCustomerCode(Owner owner) {
351	        String city3 = upperPrefix3(owner.getCity());
352	        String last3 = upperPrefix3(owner.getLastName());
353	        long sequence = countOwnersInCity(owner) + 1L;
354	        return String.format("%s-%s-%04d", city3, last3, sequence);
355	    }
356	
357	    /**
358	     * Return the upper-cased first three letters of {@code value} (or fewer when it is shorter),
359	     * the shared truncate-and-upper idiom used for each {@code customerCode} prefix segment.
360	     */
361	    private String upperPrefix3(String value) {
362	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
363	    }
364	
365	    /**
366	     * Count the owners that already exist (before this create) in the same city as {@code owner},
367	     * compared case-insensitively.
368	     */
369	    private long countOwnersInCity(Owner owner) {
370	        String city = owner.getCity();
371	        return ownerRepository.findAll().stream()
372	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
373	            .count();
374	    }
375	
376	    /**
377	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
378	     * on the given {@code date}. Used to enforce the per-day create cap.
379	     */
380	    private long countOwnersRegisteredOn(LocalDate date) {
381	        return ownerRepository.findAll().stream()
382	            .filter(existing -> date.equals(existing.getRegistrationDate()))
383	            .count();
384	    }
385	
386	    /**
387	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
388	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
389	     * are required to fall on a business day.
390	     */
391	    private LocalDate toBusinessDay(LocalDate date) {
392	        switch (date.getDayOfWeek()) {
393	            case SATURDAY:
394	                return date.plusDays(2);
395	            case SUNDAY:
396	                return date.plusDays(1);
397	            default:
398	                return date;
399	        }
400	    }
401	
402	    /**
403	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
404	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
405	     */
406	    private String generateMembershipNumber(Owner owner) {
407	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
408	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
409	    }
410	
411	    @Override
412	    @Transactional(readOnly = true)
413	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
414	        return ownerRepository.findByLastName(lastName);
415	    }
416	
417	    @Override
418	    @Transactional(readOnly = true)
419	    public Collection<Visit> findVisitsByPetId(int petId) {
420	        return visitRepository.findByPetId(petId);
421	    }
422	
423	    @Override
424	    @Transactional(readOnly = true)
425	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
426	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
427	    }
428	
429	    private <T> T findEntityById(Supplier<T> supplier) {
430	        try {
431	            return supplier.get();
432	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
433	            // Just ignore not found exceptions for Jdbc/Jpa realization
434	            return null;
435	        }
436	    }
437	
438	}
